var rDoc = (object)revitDoc as Document ?? (object)doc as Document;
var viewCollector = new FilteredElementCollector(rDoc).OfClass(typeof(View)).Cast<View>().FirstOrDefault(v => v.Name.Contains("TẦNG 2"));
var beams = new FilteredElementCollector(rDoc, viewCollector.Id)
    .OfCategory(BuiltInCategory.OST_StructuralFraming)
    .WhereElementIsNotElementType()
    .Cast<FamilyInstance>()
    .Where(b => (b.Symbol?.Name ?? "").StartsWith("B_200") || (b.Symbol?.Name ?? "").StartsWith("B_300"))
    .Take(5)
    .ToList();

var sb = new System.Text.StringBuilder();
foreach (var b in beams) {
    var pName = b.LookupParameter("STR_ElementName")?.AsString();
    var pCount = b.LookupParameter("STR_ElementCount")?.AsInteger();
    var pComments = b.LookupParameter("Comments")?.AsString();
    sb.AppendLine($"Beam {b.Id} ({b.Symbol?.Name}): STR_ElementName='{pName}', STR_ElementCount={pCount}, Comments='{pComments}'");
}
return sb.ToString();
